    43
    44  let currentUserEmail = '';
    45  let currentUserAccountID = -1;
    46
    47  Onyx.connect({
    48      key: ONYXKEYS.SESSION,
    49      callback: (value) => {
    50          currentUserEmail = value?.email ?? '';
    51          currentUserAccountID = value?.accountID ?? -1;
    52      },
    53  });
    54
    55  let allPersonalDetails: OnyxEntry<OnyxTypes.PersonalDetailsList>;
    56  Onyx.connect({
    57      key: ONYXKEYS.PERSONAL_DETAILS_LIST,
    58      callback: (value) => (allPersonalDetails = value),
    59  });
    60
    61  let quickAction: OnyxEntry<OnyxTypes.QuickAction> = {};
    62  Onyx.connect({
    63      key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
    64      callback: (value) => {
    65          quickAction = value;
    66      },
    67  });
    68
    69  let allReportActions: OnyxCollection<ReportActions>;
    70  Onyx.connect({
    71      key: ONYXKEYS.COLLECTION.REPORT_ACTIONS,
    72      waitForCollectionCallback: true,
    73      callback: (actions) => {
    74          if (!actions) {
    75              return;
    76          }
    77
    78          allReportActions = actions;
    79      },
    80  });
    81
    82  /**
    83   * Clears out the task info from the store
    84   */
    85  function clearOutTaskInfo(skipConfirmation = false) {
    86      if (skipConfirmation) {
    87          Onyx.set(ONYXKEYS.TASK, {skipConfirmation: true});
    88      } else {
    89          Onyx.set(ONYXKEYS.TASK, null);
    90      }
    91  }
    92
    93  /**
    94   * A task needs two things to be created - a title and a parent report
    95   * When you create a task report, there are a few things that happen:
    96   * A task report is created, along with a CreatedReportAction for that new task report
    97   * A reportAction indicating that a task was created is added to the parent report (share destination)
    98   * If you assign the task to someone, a reportAction is created in the chat between you and the assignee to inform them of the task
    99   *
   100   * So you have the following optimistic items potentially being created:
   101   * 1. The task report
   102   * 1a. The CreatedReportAction for the task report
   103   * 2. The TaskReportAction on the parent report
   104   * 3. The chat report between you and the assignee
   105   * 3a. The CreatedReportAction for the assignee chat report
   106   * 3b. The TaskReportAction on the assignee chat report
   107   */
   108  function createTaskAndNavigate(
   109      parentReportID: string,
   110      title: string,
   111      description: string,
   112      assigneeEmail: string,
   113      assigneeAccountID = 0,
   114      assigneeChatReport?: OnyxEntry<OnyxTypes.Report>,
   115      policyID: string = CONST.POLICY.OWNER_EMAIL_FAKE,
   116      isCreatedUsingMarkdown = false,
   117  ) {
   118      const optimisticTaskReport = ReportUtils.buildOptimisticTaskReport(currentUserAccountID, assigneeAccountID, parentReportID, title, description, policyID);
   119
   120      const assigneeChatReportID = assigneeChatReport?.reportID ?? '-1';
   121      const taskReportID = optimisticTaskReport.reportID;
   122      let assigneeChatReportOnyxData;
   123
   124      // Parent ReportAction indicating that a task has been created
   125      const optimisticTaskCreatedAction = ReportUtils.buildOptimisticCreatedReportAction(currentUserEmail);
   126      const optimisticAddCommentReport = ReportUtils.buildOptimisticTaskCommentReportAction(taskReportID, title, assigneeAccountID, `task for ${title}`, parentReportID);
   127      optimisticTaskReport.parentReportActionID = optimisticAddCommentReport.reportAction.reportActionID;
   128
   129      const currentTime = DateUtils.getDBTimeWithSkew();
   130      const lastCommentText = ReportUtils.formatReportLastMessageText(ReportActionsUtils.getReportActionText(optimisticAddCommentReport.reportAction));
   131      const parentReport = ReportUtils.getReport(parentReportID);
   132      const optimisticParentReport = {
   133          lastVisibleActionCreated: optimisticAddCommentReport.reportAction.created,
   134          lastMessageText: lastCommentText,
   135          lastActorAccountID: currentUserAccountID,
   136          lastReadTime: currentTime,
   137          lastMessageTranslationKey: '',
   138          hasOutstandingChildTask: assigneeAccountID === currentUserAccountID ? true : parentReport?.hasOutstandingChildTask,
   139      };
   140
   141      // We're only setting onyx data for the task report here because it's possible for the parent report to not exist yet (if you're assigning a task to someone you haven't chatted with before)
   142      // So we don't want to set the parent report data until we've successfully created that chat report
   143      // FOR TASK REPORT
   144      const optimisticData: OnyxUpdate[] = [
   145          {
   146              onyxMethod: Onyx.METHOD.SET,
   147              key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   148              value: {
   149                  ...optimisticTaskReport,
   150                  pendingFields: {
   151                      createChat: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   152                      reportName: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   153                      description: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   154                      managerID: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   155                  },
   156                  isOptimisticReport: true,
   157              },
   158          },
   159          {
   160              onyxMethod: Onyx.METHOD.SET,
   161              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   162              value: {[optimisticTaskCreatedAction.reportActionID]: optimisticTaskCreatedAction as OnyxTypes.ReportAction},
   163          },
   164      ];
   165
   166      // FOR TASK REPORT
   167      const successData: OnyxUpdate[] = [
   168          {
   169              onyxMethod: Onyx.METHOD.MERGE,
   170              key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   171              value: {
   172                  pendingFields: {
   173                      createChat: null,
   174                      reportName: null,
   175                      description: null,
   176                      managerID: null,
   177                  },
   178                  isOptimisticReport: false,
   179                  // BE will send a different participant. We clear the optimistic one to avoid duplicated entries
   180                  participants: {[assigneeAccountID]: null},
   181              },
   182          },
   183          {
   184              onyxMethod: Onyx.METHOD.MERGE,
   185              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   186              value: {[optimisticTaskCreatedAction.reportActionID]: {pendingAction: null}},
   187          },
   188      ];
   189
   190      // FOR TASK REPORT
   191      const failureData: OnyxUpdate[] = [
   192          {
   193              onyxMethod: Onyx.METHOD.MERGE,
   194              key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   195              value: null,
   196          },
   197          {
   198              onyxMethod: Onyx.METHOD.MERGE,
   199              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   200              value: null,
   201          },
   202      ];
   203
   204      if (assigneeChatReport) {
   205          assigneeChatReportOnyxData = ReportUtils.getTaskAssigneeChatOnyxData(
   206              currentUserAccountID,
   207              assigneeAccountID,
   208              taskReportID,
   209              assigneeChatReportID,
   210              parentReportID,
   211              title,
   212              assigneeChatReport,
   213          );
   214
   215          optimisticData.push(...assigneeChatReportOnyxData.optimisticData);
   216          successData.push(...assigneeChatReportOnyxData.successData);
   217          failureData.push(...assigneeChatReportOnyxData.failureData);
   218      }
   219
   220      // Now that we've created the optimistic chat report and chat reportActions, we can update the parent report data
   221      // FOR PARENT REPORT (SHARE DESTINATION)
   222      optimisticData.push(
   223          {
   224              onyxMethod: Onyx.METHOD.MERGE,
   225              key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   226              value: optimisticParentReport,
   227          },
   228          {
   229              onyxMethod: Onyx.METHOD.MERGE,
   230              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   231              value: {[optimisticAddCommentReport.reportAction.reportActionID]: optimisticAddCommentReport.reportAction as OnyxTypes.ReportAction},
   232          },
   233      );
   234
   235      const shouldUpdateNotificationPreference = !isEmptyObject(parentReport) && ReportUtils.getReportNotificationPreference(parentReport) === CONST.REPORT.NOTIFICATION_PREFERENCE.HIDDEN;
   236      if (shouldUpdateNotificationPreference) {
   237          optimisticData.push({
   238              onyxMethod: Onyx.METHOD.MERGE,
   239              key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   240              value: {
   241                  participants: {
   242                      [currentUserAccountID]: {notificationPreference: CONST.REPORT.NOTIFICATION_PREFERENCE.ALWAYS},
   243                  },
   244              },
   245          });
   246      }
   247
   248      // FOR QUICK ACTION NVP
   249      optimisticData.push({
   250          onyxMethod: Onyx.METHOD.SET,
   251          key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
   252          value: {
   253              action: CONST.QUICK_ACTIONS.ASSIGN_TASK,
   254              chatReportID: parentReportID,
   255              isFirstQuickAction: isEmptyObject(quickAction),
   256              targetAccountID: assigneeAccountID,
   257          },
   258      });
   259      failureData.push({
   260          onyxMethod: Onyx.METHOD.SET,
   261          key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
   262          value: quickAction ?? null,
   263      });
   264
   265      // If needed, update optimistic data for parent report action of the parent report.
   266      const optimisticParentReportData = ReportUtils.getOptimisticDataForParentReportAction(parentReportID, currentTime, CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD);
   267      optimisticParentReportData.forEach((parentReportData) => {
   268          if (isEmptyObject(parentReportData)) {
   269              return;
   270          }
   271          optimisticData.push(parentReportData);
   272      });
   273
   274      // FOR PARENT REPORT (SHARE DESTINATION)
   275      successData.push({
   276          onyxMethod: Onyx.METHOD.MERGE,
   277          key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   278          value: {[optimisticAddCommentReport.reportAction.reportActionID]: {pendingAction: null, isOptimisticAction: null}},
   279      });
   280
   281      // FOR PARENT REPORT (SHARE DESTINATION)
   282      failureData.push({
   283          onyxMethod: Onyx.METHOD.MERGE,
   284          key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   285          value: {
   286              [optimisticAddCommentReport.reportAction.reportActionID]: {
   287                  errors: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('task.genericCreateTaskFailureMessage'),
   288              },
   289          },
   290      });
   291      failureData.push({
   292          onyxMethod: Onyx.METHOD.MERGE,
   293          key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   294          value: {
