   322  /**
   323   * @returns the object to update `report.hasOutstandingChildTask`
   324   */
   325  function getOutstandingChildTask(taskReport: OnyxEntry<OnyxTypes.Report>) {
   326      const parentReportActions = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReport?.parentReportID}`] ?? {};
   327      return Object.values(parentReportActions).some((reportAction) => {
   328          if (String(reportAction.childReportID) === String(taskReport?.reportID)) {
   329              return false;
   330          }
   331
   332          if (
   333              reportAction.childType === CONST.REPORT.TYPE.TASK &&
   334              reportAction?.childStateNum === CONST.REPORT.STATE_NUM.OPEN &&
   335              reportAction?.childStatusNum === CONST.REPORT.STATUS_NUM.OPEN &&
   336              ReportActionsUtils.getReportActionMessage(reportAction)?.isDeletedParentAction
   337          ) {
   338              return true;
   339          }
   340
   341          return false;
   342      });
   343  }
