   345  /**
   346   * Complete a task
   347   */
   348  function completeTask(taskReport: OnyxEntry<OnyxTypes.Report>) {
   349      const taskReportID = taskReport?.reportID ?? '-1';
   350      const message = `marked as complete`;
   351      const completedTaskReportAction = ReportUtils.buildOptimisticTaskReportAction(taskReportID, CONST.REPORT.ACTIONS.TYPE.TASK_COMPLETED, message);
   352      const parentReport = getParentReport(taskReport);
   353      const optimisticData: OnyxUpdate[] = [
   354          {
   355              onyxMethod: Onyx.METHOD.MERGE,
   356              key: `${ONYXKEYS.COLLECTION.REPORT}${taskReportID}`,
   357              value: {
   358                  stateNum: CONST.REPORT.STATE_NUM.APPROVED,
   359                  statusNum: CONST.REPORT.STATUS_NUM.APPROVED,
   360                  lastReadTime: DateUtils.getDBTime(),
   361              },
   362          },
   363          {
   364              onyxMethod: Onyx.METHOD.MERGE,
   365              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReportID}`,
   366              value: {[completedTaskReportAction.reportActionID]: completedTaskReportAction as OnyxTypes.ReportAction},
   367          },
   368      ];
   369
   370      const successData: OnyxUpdate[] = [
   371          {
   372              onyxMethod: Onyx.METHOD.MERGE,
   373              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReportID}`,
   374              value: {
   375                  [completedTaskReportAction.reportActionID]: {
   376                      pendingAction: null,
   377                  },
   378              },
   379          },
   380      ];
   381
   382      const failureData: OnyxUpdate[] = [
   383          {
   384              onyxMethod: Onyx.METHOD.MERGE,
   385              key: `${ONYXKEYS.COLLECTION.REPORT}${taskReportID}`,
   386              value: {
   387                  stateNum: CONST.REPORT.STATE_NUM.OPEN,
   388                  statusNum: CONST.REPORT.STATUS_NUM.OPEN,
   389                  lastReadTime: taskReport?.lastReadTime ?? null,
   390              },
   391          },
   392          {
   393              onyxMethod: Onyx.METHOD.MERGE,
   394              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${taskReportID}`,
   395              value: {
   396                  [completedTaskReportAction.reportActionID]: {
   397                      errors: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('task.messages.error'),
   398                  },
   399              },
   400          },
   401      ];
   402
   403      if (parentReport?.hasOutstandingChildTask) {
   404          const hasOutstandingChildTask = getOutstandingChildTask(taskReport);
   405          optimisticData.push({
   406              onyxMethod: Onyx.METHOD.MERGE,
   407              key: `${ONYXKEYS.COLLECTION.REPORT}${taskReport?.parentReportID}`,
   408              value: {
   409                  hasOutstandingChildTask,
   410              },
   411          });
   412          failureData.push({
   413              onyxMethod: Onyx.METHOD.MERGE,
   414              key: `${ONYXKEYS.COLLECTION.REPORT}${taskReport?.parentReportID}`,
   415              value: {
   416                  hasOutstandingChildTask: parentReport?.hasOutstandingChildTask,
   417              },
   418          });
   419      }
   420
   421      const parameters: CompleteTaskParams = {
   422          taskReportID,
   423          completedTaskReportActionID: completedTaskReportAction.reportActionID,
   424      };
   425
   426      playSound(SOUNDS.SUCCESS);
   427      API.write(WRITE_COMMANDS.COMPLETE_TASK, parameters, {optimisticData, successData, failureData});
   428      Report.notifyNewAction(taskReportID, currentUserAccountID);
