   592  function editTaskAssignee(report: OnyxTypes.Report, sessionAccountID: number, assigneeEmail: string, assigneeAccountID: number | null = 0, assigneeChatReport?: OnyxEntry<OnyxTypes.Report>) {
   593      // Create the EditedReportAction on the task
   594      const editTaskReportAction = ReportUtils.buildOptimisticChangedTaskAssigneeReportAction(assigneeAccountID ?? 0);
   595      const reportName = report.reportName?.trim();
   596
   597      let assigneeChatReportOnyxData;
   598      const assigneeChatReportID = assigneeChatReport ? assigneeChatReport.reportID : '-1';
   599      const parentReport = getParentReport(report);
   600      const taskOwnerAccountID = getTaskOwnerAccountID(report);
   601      const optimisticReport: OptimisticReport = {
   602          reportName,
   603          managerID: assigneeAccountID ?? report.managerID,
   604          pendingFields: {
   605              ...(assigneeAccountID && {managerID: CONST.RED_BRICK_ROAD_PENDING_ACTION.UPDATE}),
   606          },
   607          participants: {
   608              [currentUserAccountID]: {
   609                  notificationPreference:
   610                      [assigneeAccountID, taskOwnerAccountID].includes(currentUserAccountID) && !parentReport
   611                          ? CONST.REPORT.NOTIFICATION_PREFERENCE.ALWAYS
   612                          : CONST.REPORT.NOTIFICATION_PREFERENCE.HIDDEN,
   613              },
   614          },
   615      };
   616      const successReport: NullishDeep<OnyxTypes.Report> = {pendingFields: {...(assigneeAccountID && {managerID: null})}};
   617
   618      const optimisticData: OnyxUpdate[] = [
   619          {
   620              onyxMethod: Onyx.METHOD.MERGE,
   621              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${report.reportID}`,
   622              value: {[editTaskReportAction.reportActionID]: editTaskReportAction as OnyxTypes.ReportAction},
   623          },
   624          {
   625              onyxMethod: Onyx.METHOD.MERGE,
   626              key: `${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`,
   627              value: optimisticReport,
   628          },
   629      ];
   630
   631      const successData: OnyxUpdate[] = [
   632          {
   633              onyxMethod: Onyx.METHOD.MERGE,
   634              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${report.reportID}`,
   635              value: {[editTaskReportAction.reportActionID]: {pendingAction: null}},
   636          },
   637          {
   638              onyxMethod: Onyx.METHOD.MERGE,
   639              key: `${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`,
   640              value: successReport,
   641          },
   642      ];
   643
   644      const failureData: OnyxUpdate[] = [
   645          {
   646              onyxMethod: Onyx.METHOD.MERGE,
   647              key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${report.reportID}`,
   648              value: {[editTaskReportAction.reportActionID]: {pendingAction: null}},
   649          },
   650          {
   651              onyxMethod: Onyx.METHOD.MERGE,
   652              key: `${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`,
   653              value: {managerID: report.managerID},
   654          },
   655      ];
   656
   657      if (currentUserAccountID === assigneeAccountID) {
   658          if (!isEmptyObject(parentReport)) {
   659              optimisticData.push({
   660                  onyxMethod: Onyx.METHOD.MERGE,
   661                  key: `${ONYXKEYS.COLLECTION.REPORT}${parentReport.reportID}`,
   662                  value: {hasOutstandingChildTask: true},
   663              });
   664              failureData.push({
   665                  onyxMethod: Onyx.METHOD.MERGE,
   666                  key: `${ONYXKEYS.COLLECTION.REPORT}${parentReport.reportID}`,
   667                  value: {hasOutstandingChildTask: parentReport?.hasOutstandingChildTask},
   668              });
   669          }
   670      }
   671
   672      if (report.managerID === currentUserAccountID) {
   673          const hasOutstandingChildTask = getOutstandingChildTask(report);
   674          if (!isEmptyObject(parentReport)) {
   675              optimisticData.push({
   676                  onyxMethod: Onyx.METHOD.MERGE,
   677                  key: `${ONYXKEYS.COLLECTION.REPORT}${parentReport.reportID}`,
   678                  value: {hasOutstandingChildTask},
   679              });
   680              failureData.push({
   681                  onyxMethod: Onyx.METHOD.MERGE,
   682                  key: `${ONYXKEYS.COLLECTION.REPORT}${parentReport.reportID}`,
   683                  value: {hasOutstandingChildTask: parentReport?.hasOutstandingChildTask},
   684              });
   685          }
   686      }
   687
   688      // If we make a change to the assignee, we want to add a comment to the assignee's chat
   689      // Check if the assignee actually changed
   690      if (assigneeAccountID && assigneeAccountID !== report.managerID && assigneeAccountID !== sessionAccountID && assigneeChatReport) {
   691          optimisticReport.participants = {
   692              ...(optimisticReport.participants ?? {}),
   693              [assigneeAccountID]: {
   694                  notificationPreference: CONST.REPORT.NOTIFICATION_PREFERENCE.ALWAYS,
   695              },
   696          };
   697
   698          assigneeChatReportOnyxData = ReportUtils.getTaskAssigneeChatOnyxData(
   699              currentUserAccountID,
   700              assigneeAccountID,
   701              report.reportID,
   702              assigneeChatReportID ?? '-1',
   703              report.parentReportID ?? '-1',
   704              reportName ?? '',
   705              assigneeChatReport,
   706          );
   707
   708          if (assigneeChatReport?.isOptimisticReport && assigneeChatReport.pendingFields?.createChat !== CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD) {
   709              // BE will send a different participant. We clear the optimistic one to avoid duplicated entries
   710              successReport.participants = {[assigneeAccountID]: null};
   711          }
   712
   713          optimisticData.push(...assigneeChatReportOnyxData.optimisticData);
   714          successData.push(...assigneeChatReportOnyxData.successData);
   715          failureData.push(...assigneeChatReportOnyxData.failureData);
   716      }
   717
   718      const parameters: EditTaskAssigneeParams = {
   719          taskReportID: report.reportID,
   720          assignee: assigneeEmail,
   721          editedTaskReportActionID: editTaskReportAction.reportActionID,
   722          assigneeChatReportID,
   723          assigneeChatReportActionID: assigneeChatReportOnyxData?.optimisticAssigneeAddComment?.reportAction.reportActionID,
   724          assigneeChatCreatedReportActionID: assigneeChatReportOnyxData?.optimisticChatCreatedReportAction?.reportActionID,
   725      };
   726
   727      API.write(WRITE_COMMANDS.EDIT_TASK_ASSIGNEE, parameters, {optimisticData, successData, failureData});
   728      Report.notifyNewAction(report.reportID, currentUserAccountID);
   729  }
