   774  function setNewOptimisticAssignee(assigneeLogin: string, assigneeAccountID: number) {
   775      const report: ReportUtils.OptimisticChatReport = ReportUtils.buildOptimisticChatReport([assigneeAccountID, currentUserAccountID]);
   776
   777      // When assigning a task to a new user, by default we share the task in their DM
   778      // However, the DM doesn't exist yet - and will be created optimistically once the task is created
   779      // We don't want to show the new DM yet, because if you select an assignee and then change the assignee, the previous DM will still be shown
   780      // So here, we create it optimistically to share it with the assignee, but we have to hide it until the task is created
   781      report.isHidden = true;
   782      Onyx.set(`${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`, report);
   783
   784      const optimisticPersonalDetailsListAction: OnyxTypes.PersonalDetails = {
   785          accountID: assigneeAccountID,
   786          avatar: allPersonalDetails?.[assigneeAccountID]?.avatar,
   787          displayName: allPersonalDetails?.[assigneeAccountID]?.displayName ?? assigneeLogin,
   788          login: assigneeLogin,
   789      };
   790      Onyx.merge(ONYXKEYS.PERSONAL_DETAILS_LIST, {[assigneeAccountID]: optimisticPersonalDetailsListAction});
   791      return {assignee: optimisticPersonalDetailsListAction, assigneeReport: report};
   792  }
