   794  /**
   795   * Sets the assignee value for the task and checks for an existing chat with the assignee
   796   * If there is no existing chat, it creates an optimistic chat report
   797   * It also sets the shareDestination as that chat report if a share destination isn't already set
   798   */
   799  function setAssigneeValue(
   800      assigneeEmail: string,
   801      assigneeAccountID: number,
   802      shareToReportID?: string,
   803      chatReport?: OnyxEntry<OnyxTypes.Report>,
   804      isCurrentUser = false,
   805      skipShareDestination = false,
   806  ): OnyxEntry<OnyxTypes.Report> | undefined {
   807      let report: OnyxEntry<OnyxTypes.Report> | undefined = chatReport;
   808      if (isCurrentUser) {
   809          const selfDMReportID = ReportUtils.findSelfDMReportID();
   810          // If there is no share destination set, automatically set it to the assignee chat report
   811          // This allows for a much quicker process when creating a new task and is likely the desired share destination most times
   812          if (!shareToReportID && !skipShareDestination) {
   813              setShareDestinationValue(selfDMReportID ?? '-1');
   814          }
   815      } else {
   816          // Check for the chatReport by participants IDs
   817          if (!report) {
   818              report = ReportUtils.getChatByParticipants([assigneeAccountID, currentUserAccountID]);
   819          }
   820          // If chat report is still not found we need to build new optimistic chat report
   821          if (!report) {
   822              report = setNewOptimisticAssignee(assigneeEmail, assigneeAccountID).assigneeReport;
   823          }
   824
   825          // The optimistic field may not exist in the existing report and it can be overridden by the optimistic field of previous report data when merging the assignee chat report
   826          // Therefore, we should add these optimistic fields here to prevent incorrect merging, which could lead to the creation of duplicate actions for an existing report
   827          setAssigneeChatReport({
   828              ...report,
   829              isOptimisticReport: report?.isOptimisticReport ?? false,
   830              pendingFields: report?.pendingFields,
   831              pendingAction: report?.pendingAction,
   832          });
   833
   834          // If there is no share destination set, automatically set it to the assignee chat report
   835          // This allows for a much quicker process when creating a new task and is likely the desired share destination most times
   836          if (!shareToReportID && !skipShareDestination) {
   837              setShareDestinationValue(report?.reportID ?? '-1');
   838          }
   839      }
   840
   841      // This is only needed for creation of a new task and so it should only be stored locally
   842      Onyx.merge(ONYXKEYS.TASK, {assignee: assigneeEmail, assigneeAccountID});
   843
   844      // When we're editing the assignee, we immediately call editTaskAssignee. Since setting the assignee is async,
   845      // the chatReport is not yet set when editTaskAssignee is called. So we return the chatReport here so that
   846      // editTaskAssignee can use it.
   847      return report;
   848  }
